<script setup>
defineProps({rows:{type:Array,default:()=>[]},selected:String});defineEmits(['select']);const food=row=>row.review?.fields?.food_record||row.food_record;const allergy={unknown:'미확인',source_declared:'원문 표시 있음',reviewed:'표시사항 검토 완료'};
</script><template><div class="table-scroll standardized-food-table"><table><thead><tr><th>식품명</th><th>업체</th><th>공통식품코드</th><th>맛·종류</th><th>낱개 규격</th><th>포장 수량</th><th>전체 규격</th><th>판매 단위</th><th>산지·원산지</th><th>등급</th><th>알레르기 확인</th><th>검토</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="['clickable',{chosen:selected===row.id}]" @click="$emit('select',row.id)"><template v-if="food(row)"><td><button class="link" @click.stop="$emit('select',row.id)">{{food(row).food_name}}</button></td><td>{{food(row).company_name}}</td><td>{{food(row).food_code}}</td><td>{{food(row).attributes.flavor}}</td><td>{{food(row).specification.piece_quantity}}{{food(row).specification.piece_unit}}</td><td>{{food(row).specification.pack_count}}</td><td>{{food(row).specification.quantity}}{{food(row).specification.unit}}</td><td>{{food(row).specification.sales_unit}}</td><td>{{food(row).attributes.origin_region||food(row).attributes.origin_country}}</td><td>{{food(row).attributes.quality_grade}}</td><td>{{allergy[food(row).allergens.review_status]}}</td><td>{{{confirmed:'확인',skipped:'제외',pending:'대기'}[row.review?.status]||'대기'}}</td></template></tr></tbody></table></div></template>
<style scoped>.standardized-food-table{max-height:300px;overflow:auto}.standardized-food-table th{position:sticky;top:0;background:#f5f8f6;z-index:1}.standardized-food-table td{white-space:nowrap}.chosen{background:#edf6ef}</style>
